// Generated by `npm run words`. Edit scripts/*.txt instead.
const PACKED: Record<number, string> = {
  3: '',
  4: '',
  5: '',
  6: '',
  7: '',
  8: '',
};

/** Every word a player may guess, by length. */
export const ALLOWED: Record<number, ReadonlySet<string>> = Object.fromEntries(
  Object.entries(PACKED).map(([n, s]) => [n, new Set(s.match(new RegExp(`.{${n}}`, 'g')))]),
);
